function clone(v){return JSON.parse(JSON.stringify(v))}function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(msg){const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),3200)}function setNotice(msg){const n=document.getElementById('notice');if(!n)return;n.textContent=msg;n.classList.add('show')}function clearNotice(){const n=document.getElementById('notice');if(n)n.classList.remove('show')}
function initFirebase(){try{if(!firebase.apps.length)firebase.initializeApp(firebaseConfig);auth=firebase.auth();db=firebase.database();firebaseReady=true;auth.onAuthStateChanged(async u=>{currentUser=u;userProfile=u?await loadProfile(u.uid):null;syncAccountButton();if(document.body.dataset.page!=='admin')renderAccount();});}catch(e){console.error(e);toast('Não foi possível conectar ao Firebase. Confira a configuração.')}}
async function dbGet(path){if(!db)throw Error('Banco indisponível');const s=await db.ref(path).once('value');return s.val()}async function dbSet(path,val){if(!db)throw Error('Banco indisponível');return db.ref(path).set(val)}async function dbUpdate(path,val){return db.ref(path).update(val)}async function dbPush(path,val){const r=db.ref(path).push();await r.set(val);return r.key}
async function loadSettings(){try{const remote=await dbGet('uniaoFitness/settings');settings={...clone(DEFAULT_SETTINGS),...(remote||{})};if(!Array.isArray(settings.welcome))settings.welcome=clone(DEFAULT_SETTINGS.welcome);if(!Array.isArray(settings.fields))settings.fields=clone(DEFAULT_SETTINGS.fields);if(!Array.isArray(settings.sponsors))settings.sponsors=[];if(!Array.isArray(settings.sections))settings.sections=[];if(!settings.payment)settings.payment=clone(DEFAULT_SETTINGS.payment);}catch(e){settings={...clone(DEFAULT_SETTINGS),...(JSON.parse(localStorage.getItem('uf-settings')||'{}'))}}applyBranding();}
function applyBranding(){document.documentElement.style.setProperty('--accent',settings.accent||'#f5c400');document.documentElement.style.setProperty('--hero-bg',settings.heroBackground?`url("${settings.heroBackground}")`:'none');document.documentElement.style.setProperty('--account-bg',settings.accountBackground?`url("${settings.accountBackground}")`:'none');document.documentElement.style.setProperty('--font',settings.font||'Arial, sans-serif');const h=document.getElementById('siteHeader');if(h){h.style.background=settings.headerColor||'#fff';if(settings.heroBackground){h.style.backgroundImage=`linear-gradient(90deg,rgba(255,255,255,.9),rgba(255,255,255,.72)),url("${settings.heroBackground}")`;h.style.backgroundSize='cover';h.style.backgroundPosition='center'}else h.style.backgroundImage='none'}const name=document.getElementById('brandName');if(name)name.textContent=settings.name||DEFAULT_SETTINGS.name;const logo=document.getElementById('headerLogo');if(logo){logo.src=settings.headerLogo||'';logo.style.display=settings.headerLogo?'block':'none';logo.style.width=(settings.logoSize||42)+'px';logo.style.height=(settings.logoSize||42)+'px'}const dev=document.getElementById('footerDeveloperLogo');if(dev){dev.src=settings.developerLogo||'';dev.style.display=settings.developerLogo?'inline-block':'none';dev.style.width=(settings.developerLogoSize||35)+'px'}const dn=document.getElementById('developerName');if(dn)dn.textContent=settings.developerName||'SAN7 Tecnologia';const title=document.getElementById('eventTitle');if(title)title.textContent=settings.eventTitle||'Inscrições abertas';const desc=document.getElementById('eventDescription');if(desc)desc.textContent=settings.eventDescription||'';document.title=settings.name||'União Fitness'}
function uploadCloudinary(file,resource='image'){return new Promise((resolve,reject)=>{if(!file)return reject(Error('Selecione um arquivo'));const form=new FormData();form.append('file',file);form.append('upload_preset',UPLOAD_PRESET);const xhr=new XMLHttpRequest();const button=document.activeElement?.closest?.('button')||document.querySelector('.is-loading');if(button)startButtonProgress(button);xhr.open('POST',`https://api.cloudinary.com/v1_1/${CLOUD_NAME}/${resource}/upload`);xhr.upload.onprogress=e=>{if(button&&e.lengthComputable)button.style.setProperty('--progress',`${Math.round(e.loaded/e.total*100)}%`)};xhr.onload=()=>{try{const d=JSON.parse(xhr.responseText);if(xhr.status>=200&&xhr.status<300&&d.secure_url)resolve(d.secure_url);else reject(Error(d.error?.message||'Falha no envio da imagem.'))}catch(e){reject(e)}finally{if(button)stopButtonProgress(button)}};xhr.onerror=()=>{if(button)stopButtonProgress(button);reject(Error('Falha de conexão durante o envio.'))};xhr.send(form)})}
function startButtonProgress(button){if(!button)return;button.classList.add('is-loading');button.setAttribute('aria-busy','true');button.style.setProperty('--progress','18%')}function stopButtonProgress(button){if(!button)return;button.classList.remove('is-loading');button.removeAttribute('aria-busy');button.style.removeProperty('--progress')}
function maskCPF(v){return v.replace(/\D/g,'').slice(0,11).replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2')}function maskDate(v){return v.replace(/\D/g,'').slice(0,8).replace(/(\d{2})(\d)/,'$1-$2').replace(/(\d{2})-(\d{2})(\d)/,'$1-$2-$3')}function digits(v){return String(v||'').replace(/\D/g,'')}function validCPF(v){const s=digits(v);if(s.length!==11||/^([0-9])\1+$/.test(s))return false;let sum=0;for(let i=0;i<9;i++)sum+=+s[i]*(10-i);let d=(sum*10)%11;if(d===10)d=0;if(d!==+s[9])return false;sum=0;for(let i=0;i<10;i++)sum+=+s[i]*(11-i);d=(sum*10)%11;if(d===10)d=0;return d===+s[10]}
function bindFloating(root=document){root.querySelectorAll('.floating-field input,.floating-field select,.floating-field textarea').forEach(input=>{const wrap=input.closest('.floating-field');const refresh=()=>{wrap.classList.toggle('filled',!!input.value);if(input.dataset.touched&&input.required&&!input.value.trim())wrap.classList.add('invalid');else if(input.dataset.touched&&input.type==='email'&&input.value&&!input.validity.valid)wrap.classList.add('invalid');else wrap.classList.remove('invalid')};input.addEventListener('focus',refresh);input.addEventListener('blur',()=>{input.dataset.touched='1';refresh()});input.addEventListener('input',()=>{if(input.name==='cpf')input.value=maskCPF(input.value);if(input.name==='birthDate')input.value=maskDate(input.value);refresh()});refresh()})}
function showView(view){document.querySelectorAll('#mainContent>section').forEach(s=>s.classList.add('hidden'));const target=document.getElementById(view+'View');if(target)target.classList.remove('hidden');if(view==='home')document.getElementById('homeView')?.classList.remove('hidden');document.getElementById('siteMenu')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});clearNotice();if(view==='register')prepareRegistration();if(view==='account')renderAccount();if(view==='lookup')document.getElementById('lookupResults').innerHTML='';}
function showModal(title,body,actions=''){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Fechar">×</button><h2>${esc(title)}</h2><div class="modal-body">${body}</div>${actions?`<div class="admin-actions">${actions}</div>`:''}</div></div>`;root.querySelector('.modal-close').onclick=()=>root.innerHTML='';root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''})}
function showTerms(){showModal('Termos de uso',`<div style="white-space:pre-wrap;line-height:1.7">${esc(settings.terms||DEFAULT_SETTINGS.terms)}</div>`)}
function renderWelcome(){const root=document.getElementById('welcomeCarousel');if(!root)return;const slides=(settings.welcome||[]).filter(x=>x.image||x.title||x.description);if(!slides.length){root.innerHTML='';return}root.innerHTML=slides.map((s,i)=>`<article class="welcome-slide ${i?'hidden':''}" data-slide="${i}">${s.image?`<img src="${esc(s.image)}" alt="">`:''}<div class="welcome-copy"><h2>${esc(s.title||'Bem-vindo')}</h2><p>${esc(s.description||'')}</p>${s.buttonText?`<button class="btn" data-view="${esc(s.buttonAction||'register')}">${esc(s.buttonText)}</button>`:''}</div></article>`).join('')+(slides.length>1?`<button class="carousel-arrow prev" aria-label="Anterior">‹</button><button class="carousel-arrow next" aria-label="Próximo">›</button><div class="carousel-dots">${slides.map((s,i)=>`<button data-dot="${i}" class="${i?'':'active'}" aria-label="Slide ${i+1}"></button>`).join('')}</div>`:'');let index=0;const activate=n=>{index=(n+slides.length)%slides.length;root.querySelectorAll('[data-slide]').forEach((el,i)=>el.classList.toggle('hidden',i!==index));root.querySelectorAll('[data-dot]').forEach((el,i)=>el.classList.toggle('active',i===index))};root.querySelector('.prev')?.addEventListener('click',()=>activate(index-1));root.querySelector('.next')?.addEventListener('click',()=>activate(index+1));root.querySelectorAll('[data-dot]').forEach(el=>el.addEventListener('click',()=>activate(+el.dataset.dot)));if(carouselTimer)clearInterval(carouselTimer);if(slides.length>1)carouselTimer=setInterval(()=>activate(index+1),2000)}
function renderSections(){const root=document.getElementById('homeSections');if(!root)return;root.innerHTML=(settings.sections||[]).map(s=>{if(s.type==='image')return `<section class="content-block"><img src="${esc(s.content)}" alt="${esc(s.title||'')}"></section>`;if(s.type==='video')return `<section class="content-block"><h2>${esc(s.title||'')}</h2><video controls playsinline src="${esc(s.content)}"></video></section>`;if(s.type==='html')return `<section class="content-block">${s.content||''}</section>`;if(s.type==='imageText')return `<section class="content-block"><h2>${esc(s.title||'')}</h2><img src="${esc(s.content)}" alt=""><p>${esc(s.text||'')}</p></section>`;return `<section class="content-block"><h2>${esc(s.title||'')}</h2><p>${esc(s.content||'')}</p></section>`}).join('')}
function renderSponsors(){const root=document.getElementById('sponsorList');if(!root)return;root.innerHTML=(settings.sponsors||[]).map(s=>`<img src="${esc(s.url||s)}" alt="Patrocinador">`).join('');document.getElementById('sponsorsSection')?.classList.toggle('hidden',!(settings.sponsors||[]).length)}
function syncAccountButton(){const b=document.querySelector('[data-view="account"]');if(b)b.textContent=currentUser?'Minha conta':'Entrar / Minha conta'}
function buildField(field,value=''){const type=field.type||'text';if(type==='textarea')return `<label class="floating-field ${field.wide?'field-wide':''}"><span>${esc(field.label)}${field.required?' *':''}</span><textarea name="${esc(field.key)}" ${field.required?'required':''}>${esc(value||'')}</textarea></label>`;if(type==='select')return `<label class="floating-field ${field.wide?'field-wide':''}"><span>${esc(field.label)}${field.required?' *':''}</span><select name="${esc(field.key)}" ${field.required?'required':''}><option value="">Selecione</option>${(field.options||[]).map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;if(type==='file')return `<label class="floating-field ${field.wide?'field-wide':''}"><span>${esc(field.label)}${field.required?' *':''}</span><input type="file" name="${esc(field.key)}" accept="image/*" ${field.required?'required':''}></label>`;return `<label class="floating-field ${field.wide?'field-wide':''}"><span>${esc(field.label)}${field.required?' *':''}</span><input name="${esc(field.key)}" type="${['email','tel','number','date','password'].includes(type)?type:'text'}" value="${esc(value||'')}" ${field.required?'required':''} ${field.key==='phone'?'inputmode="tel"':''}></label>`}
function prepareRegistration(){const root=document.getElementById('registrationFields');if(!root)return;if(!currentUser){renderAccount('login','register');return}const p=userProfile||{};root.innerHTML=(settings.fields||DEFAULT_SETTINGS.fields).map(f=>buildField(f,({fullName:p.fullName,address:p.address,email:currentUser.email,phone:p.phone,city:p.city,age:p.age,cpf:p.cpf,birthDate:p.birthDate})[f.key]||'')).join('');bindFloating(root);const coupon=(settings.coupons||[]).find(c=>c.code);}
async function loadProfile(uid){try{return await dbGet('uniaoFitness/accounts/'+uid)}catch(e){return JSON.parse(localStorage.getItem('uf-profile-'+uid)||'null')}}
function renderAccount(mode,returnTo='home'){const root=document.getElementById('accountView');if(!root)return;if(!currentUser||mode==='login'||mode==='signup'||mode==='recover'){renderAuth(root,mode||'login',returnTo);return}const p=userProfile||{};root.innerHTML=`<div class="account-card account-modern"><div class="account-cover"><span>ÁREA DO PARTICIPANTE</span><strong>Minha conta</strong></div><div class="profile-head"><img class="profile-photo" src="${esc(p.photo||'https://placehold.co/120x120?text=Perfil')}" alt="Foto de perfil"><div><h2>${esc(p.fullName||currentUser.email||'Minha conta')}</h2><p>${esc(p.email||currentUser.email||'')} · ${esc(p.phone||'Telefone não informado')}</p></div></div><div class="account-actions"><button class="btn btn-primary" id="editProfile">Editar dados</button><button class="btn btn-outline" id="logoutButton">Sair da conta</button></div><h2>Minhas inscrições</h2><div id="myRegistrations"><p class="empty-state">Carregando inscrições…</p></div></div>`;root.querySelector('#editProfile').onclick=()=>renderProfileEditor();root.querySelector('#logoutButton').onclick=async()=>{await auth.signOut();localStorage.removeItem('uf-current-user');showView('home');toast('Você saiu da sua conta.')};loadMyRegistrations().then(rows=>{const el=document.getElementById('myRegistrations');if(!el)return;if(!rows.length){el.innerHTML='<p class="empty-state">Você ainda não tem inscrições.</p>';return}el.innerHTML=rows.map(r=>`<article class="registration-card" data-reg="${esc(r.id)}"><div><h3>${esc(r.eventName||settings.name)}</h3><p>Inscrição ${esc(r.number||'—')} · ${esc(r.createdAt?new Date(r.createdAt).toLocaleDateString('pt-BR'):'')}</p></div><span class="status ${r.paymentStatus==='paid'?'paid':settings.payment.enabled?'pending':'free'}">${r.paymentStatus==='paid'?'Pagamento validado':settings.payment.enabled?'Aguardando confirmação':'Inscrição confirmada'}</span></article>`).join('');el.querySelectorAll('[data-reg]').forEach(card=>card.onclick=()=>openMyRegistration(card.dataset.reg,rows))}).catch(()=>{const el=document.getElementById('myRegistrations');if(el)el.innerHTML='<p class="empty-state">Não foi possível carregar as inscrições.</p>'})}
function authErrorMessage(err){const code=err?.code||'';if(code==='auth/invalid-credential'||code==='auth/wrong-password'||code==='auth/user-not-found'||code==='auth/invalid-login-credentials')return 'E-mail/telefone ou senha incorretos. Confira seus dados e tente novamente.';if(code==='auth/too-many-requests')return 'Muitas tentativas de acesso. Aguarde alguns minutos e tente novamente.';if(code==='auth/network-request-failed')return 'Sem conexão com a internet. Verifique sua rede e tente novamente.';if(code==='auth/invalid-email')return 'O e-mail informado não é válido.';if(code==='auth/email-already-in-use')return 'Este e-mail já possui uma conta. Faça login.';if(code==='auth/weak-password')return 'A senha precisa ter pelo menos 6 caracteres.';if(/Conta não encontrada/.test(err?.message||''))return 'Não encontramos uma conta com esse telefone. Confira o número ou entre com seu e-mail.';return err?.message||'Não foi possível concluir. Tente novamente.'}
function renderAuth(root,mode='login',returnTo='home'){const signup=mode==='signup',recover=mode==='recover';root.innerHTML=`<div class="view-heading"><p class="eyebrow">MINHA CONTA</p><h1>${signup?'Criar conta':recover?'Recuperar acesso':'Entrar na sua conta'}</h1><p>${signup?'Crie sua conta uma única vez para facilitar as inscrições.':recover?'Confirme seus dados para alterar a senha.':'Entre com e-mail ou telefone e senha.'}</p></div><form id="authForm" class="form-panel">${signup?`<div class="profile-upload"><img id="signupPhotoPreview" class="profile-photo" src="https://placehold.co/120x120?text=Foto" alt="Prévia da foto"><label class="floating-field"><span>Foto de perfil obrigatória</span><input id="signupPhoto" type="file" accept="image/*" required></label></div><div class="field-grid">${buildField({key:'fullName',label:'Nome completo',required:true})}${buildField({key:'cpf',label:'CPF',required:true})}${buildField({key:'birthDate',label:'Data de nascimento',required:true})}${buildField({key:'phone',label:'Telefone',type:'tel',required:true})}${buildField({key:'address',label:'Endereço completo',required:true,wide:true})}${buildField({key:'email',label:'E-mail',type:'email',required:true})}${buildField({key:'password',label:'Criar senha',type:'password',required:true})}</div><p class="admin-note">Para entrar, você pode usar e-mail e senha. O acesso por telefone depende de o telefone estar vinculado à conta.</p>`:recover?`<div class="field-grid">${buildField({key:'cpf',label:'CPF',required:true})}${buildField({key:'birthDate',label:'Data de nascimento',required:true})}${buildField({key:'phone',label:'Telefone cadastrado',type:'tel',required:true})}${buildField({key:'newPassword',label:'Nova senha',type:'password',required:true})}</div><p class="admin-note">A recuperação por conferência de dados precisa ser implementada com validação segura no servidor. Não altere a senha apenas com dados pessoais em um site público.</p>`:`<div class="field-grid">${buildField({key:'login',label:'E-mail ou telefone',required:true})}${buildField({key:'password',label:'Senha',type:'password',required:true})}</div>`}<p id="authError" class="form-error"></p><button class="btn btn-primary submit-btn" type="submit"><span>${signup?'Criar conta':recover?'Validar dados':'Entrar'}</span><span class="spinner hidden"></span></button><div class="admin-actions">${!signup&&!recover?'<button type="button" class="btn btn-outline" id="toSignup">Criar conta</button><button type="button" class="text-button" id="toRecover">Esqueci a senha</button>':''}${signup||recover?'<button type="button" class="btn btn-outline" id="toLogin">Voltar para entrar</button>':''}</div></form>`;bindFloating(root);root.querySelector('#toSignup')?.addEventListener('click',()=>renderAccount('signup',returnTo));root.querySelector('#toRecover')?.addEventListener('click',()=>renderAccount('recover',returnTo));root.querySelector('#toLogin')?.addEventListener('click',()=>renderAccount('login',returnTo));const photo=root.querySelector('#signupPhoto');photo?.addEventListener('change',()=>{const f=photo.files[0];if(f)root.querySelector('#signupPhotoPreview').src=URL.createObjectURL(f)});root.querySelector('#authForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type=submit]'),spin=btn.querySelector('.spinner'),error=root.querySelector('#authError');error.textContent='';error.classList.remove('visible');spin.classList.remove('hidden');btn.disabled=true;startButtonProgress(btn);try{const data=Object.fromEntries(new FormData(form).entries());if(signup){const cpf=digits(data.cpf);if(!validCPF(data.cpf))throw Error('Confira o CPF informado.');const photoFile=photo.files[0];if(!photoFile)throw Error('A foto de perfil é obrigatória.');const photoUrl=await uploadCloudinary(photoFile);const cred=await auth.createUserWithEmailAndPassword(data.email.trim(),data.password);const profile={fullName:data.fullName.trim(),cpf,birthDate:data.birthDate,phone:digits(data.phone),address:data.address.trim(),email:data.email.trim(),photo:photoUrl,createdAt:Date.now()};await dbSet('uniaoFitness/accounts/'+cred.user.uid,profile);userProfile=profile;localStorage.setItem('uf-current-user',cred.user.uid);toast('Conta criada com sucesso.');if(returnTo==='register'){showView('register');setNotice('Conta criada. Complete os dados para finalizar sua inscrição.');prepareRegistration()}else showView('account');}else if(recover){throw Error('Para sua segurança, a recuperação por dados pessoais precisa de validação no servidor. Use a recuperação oficial do Firebase pelo e-mail cadastrado.')}else{let credential;const login=data.login.trim();if(login.includes('@'))credential=await auth.signInWithEmailAndPassword(login,data.password);else{const phone=digits(login);const accounts=await dbGet('uniaoFitness/accounts')||{};const match=Object.entries(accounts).find(([id,p])=>digits(p.phone)===phone);if(!match)throw Error('Conta não encontrada para este telefone. Entre com o e-mail cadastrado.');const p=match[1];credential=await auth.signInWithEmailAndPassword(p.email,data.password)}currentUser=credential.user;userProfile=await loadProfile(currentUser.uid);localStorage.setItem('uf-current-user',currentUser.uid);toast('Login realizado.');if(returnTo==='register'){showView('register');prepareRegistration()}else showView('account')}}catch(err){error.textContent=authErrorMessage(err);error.classList.add('visible')}finally{spin.classList.add('hidden');btn.disabled=false;stopButtonProgress(btn)}})}
function renderProfileEditor(){const p=userProfile||{};showModal('Editar dados',`<form id="profileEditForm" class="admin-form-grid"><label class="admin-field">Nome completo<input name="fullName" required value="${esc(p.fullName||'')}"></label><label class="admin-field">Telefone<input name="phone" required value="${esc(p.phone||'')}"></label><label class="admin-field wide">Endereço<input name="address" required value="${esc(p.address||'')}"></label><label class="admin-field wide">Nova foto de perfil<input name="photo" type="file" accept="image/*"></label></form><p id="profileEditError" class="form-error"></p>`,`<button class="btn btn-primary" id="saveProfile">Salvar alterações</button>`);document.getElementById('saveProfile').onclick=async()=>{const form=document.getElementById('profileEditForm'),data=Object.fromEntries(new FormData(form).entries()),err=document.getElementById('profileEditError');try{if(data.photo.size){data.photo=await uploadCloudinary(data.photo)}else delete data.photo;data.phone=digits(data.phone);userProfile={...userProfile,...data};await dbSet('uniaoFitness/accounts/'+currentUser.uid,userProfile);document.getElementById('modalRoot').innerHTML='';renderAccount();toast('Dados atualizados.')}catch(e){err.textContent=e.message}}}
async function loadMyRegistrations(){if(!currentUser)return[];const data=await dbGet('uniaoFitness/registrations')||{};return Object.entries(data).filter(([id,r])=>r.uid===currentUser.uid).map(([id,r])=>({...r,id})).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0))}
function verifier(number){const s=String(number).padStart(4,'0');let n=(Number(s[0])+Number(s[3]))/2;n=Math.floor(n);while(n>9)n=Math.floor(n/2);if(n<0)n=0;return n%10}
async function nextRegistrationNumber(){const snap=await dbGet('uniaoFitness/meta/lastNumber')||0;const next=Number(snap)+1;if(next>9999)throw Error('Limite de inscrições atingido para esta sequência.');await dbSet('uniaoFitness/meta/lastNumber',next);return String(next).padStart(4,'0')}
function randomToken(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789-';const bytes=new Uint8Array(46);crypto.getRandomValues(bytes);return Array.from(bytes,b=>chars[b%chars.length]).join('')}
async function submitRegistration(e){e.preventDefault();if(!currentUser){renderAccount('login','register');showView('account');return}if(!document.getElementById('termsAccepted').checked){document.getElementById('formError').textContent='Você precisa aceitar os termos de uso.';return}const form=e.currentTarget,btn=form.querySelector('button[type=submit]'),spin=btn.querySelector('.spinner');btn.disabled=true;spin.classList.remove('hidden');startButtonProgress(btn);document.getElementById('formError').textContent='';try{const all=await dbGet('uniaoFitness/registrations')||{};if(Object.values(all).some(r=>r.uid===currentUser.uid&&r.eventId===(settings.eventId||'default')))throw Error('Esta conta já possui uma inscrição neste evento.');const fd=new FormData(form),data={};for(const field of settings.fields||DEFAULT_SETTINGS.fields){const value=fd.get(field.key);if(field.type==='file'){if(value&&value.size)data[field.key]=await uploadCloudinary(value)}else data[field.key]=String(value||'').trim()}const number=await nextRegistrationNumber(),check=verifier(number),token=randomToken(),id=await dbPush('uniaoFitness/registrations',{uid:currentUser.uid,eventId:settings.eventId||'default',eventName:settings.name||DEFAULT_SETTINGS.name,number,verifier:check,token,data,profile:{fullName:userProfile?.fullName||data.fullName||'',phone:userProfile?.phone||data.phone||'',cpf:userProfile?.cpf||'',birthDate:userProfile?.birthDate||'',photo:userProfile?.photo||''},createdAt:Date.now(),paymentStatus:settings.payment?.enabled?'pending':'paid',paymentRequired:!!settings.payment?.enabled,amount:settings.payment?.amount||'',verifiedAt:settings.payment?.enabled?null:Date.now()});const r={id,uid:currentUser.uid,eventId:settings.eventId||'default',eventName:settings.name||DEFAULT_SETTINGS.name,number,verifier:check,token,data,profile:userProfile||{},createdAt:Date.now(),paymentStatus:settings.payment?.enabled?'pending':'paid',paymentRequired:!!settings.payment?.enabled};if(settings.payment?.enabled){activeRegistration=r;renderPayment(r)}else{activeRegistration=r;renderReceipt(r);showView('receipt')}toast('Inscrição registrada.')}catch(err){document.getElementById('formError').textContent=err.message||'Não foi possível concluir a inscrição.'}finally{btn.disabled=false;spin.classList.add('hidden');stopButtonProgress(btn)}}
function renderPayment(r){showView('payment');const root=document.getElementById('paymentView'),p=settings.payment||{};root.innerHTML=`<div class="view-heading"><p class="eyebrow">INSCRIÇÃO RECEBIDA</p><h1>Finalize o pagamento</h1><p>Sua inscrição ficará aguardando confirmação. O comprovante oficial será liberado após a validação.</p></div><div class="form-panel"><h2 style="margin-top:0">Valor: ${esc(p.amount||'A confirmar')}</h2><div class="timeline"><div class="timeline-step"><span class="step-no">1</span><div><h3>Copie a chave Pix</h3><p>Use a chave abaixo para realizar o pagamento no aplicativo do seu banco.</p><div class="copy-row"><code id="pixKeyText">${esc(p.pixKey||'Chave Pix não informada')}</code><button class="btn-small" id="copyPix">Copiar</button></div></div></div><div class="timeline-step"><span class="step-no">2</span><div><h3>Realize o pagamento</h3><p>Confira o valor e o destinatário antes de confirmar a transferência.</p></div></div><div class="timeline-step"><span class="step-no">3</span><div><h3>Envie o comprovante pelo WhatsApp</h3><p>${esc(p.message||'A confirmação pode levar até cinco horas após o envio do comprovante.')}</p><button class="btn btn-primary" id="sendPaymentWhatsapp">Confirmar no WhatsApp</button></div></div></div><p class="admin-note">Número da inscrição: ${esc(r.number)}-${esc(r.verifier)}. Você pode acompanhar o status em Minha conta.</p><button class="btn btn-outline" id="goAccount">Ver minhas inscrições</button></div>`;root.querySelector('#copyPix').onclick=()=>{navigator.clipboard?.writeText(p.pixKey||'').then(()=>toast('Chave Pix copiada.')).catch(()=>toast('Copie a chave manualmente.'))};root.querySelector('#sendPaymentWhatsapp').onclick=()=>{const msg=`Olá, tudo bem? Me chamo ${userProfile?.fullName||r.data?.fullName||''}, portador(a) do CPF ${userProfile?.cpf||''}. Me inscrevi no evento ${r.eventName}, inscrição ${r.number}-${r.verifier}. Já realizei o pagamento e estou enviando o comprovante.`;const phone=digits(p.whatsapp||'');window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener')};root.querySelector('#goAccount').onclick=()=>showView('account')}
async function openMyRegistration(id,rows){const r=rows.find(x=>x.id===id);if(!r)return;if(r.paymentRequired&&r.paymentStatus!=='paid'){showModal('Pagamento em validação',`<div class="timeline-step"><span class="step-no">◷</span><div><h3>Aguardando confirmação</h3><p>A equipe responsável validará o pagamento em até cinco horas após receber o comprovante. O comprovante oficial ficará disponível após a confirmação.</p><p>Inscrição: ${esc(r.number)}-${esc(r.verifier)}</p></div></div>`);return}activeRegistration=r;await renderReceipt(r);showView('receipt')}
function maskedCPF(v){const s=digits(v);return s.length===11?'***.***.**'+s.slice(-2)+'-**':v?'***.***.**'+digits(v).slice(-2):'Não informado'}
async function renderReceipt(r){const root=document.getElementById('receiptView');if(!root)return;const data=r.data||{},p=r.profile||userProfile||{};const qrValue=`UF|${r.id}|${r.number}-${r.verifier}|${r.token||''}`;root.innerHTML=`<div class="view-heading"><p class="eyebrow">DOCUMENTO DIGITAL</p><h1>Comprovante de inscrição</h1><p>Guarde este documento para consulta e validação.</p></div><article id="receiptDocument" class="document-card" style="--watermark:url('${esc(settings.watermark||settings.headerLogo||'')}')"><div class="receipt-top">${settings.headerLogo?`<img class="receipt-logo" style="width:${Number(settings.receiptLogoSize||100)}px" src="${esc(settings.headerLogo)}" alt="Logo">`:''}<h2>${esc(settings.name||'Academia União Fitness')}</h2><p>Comprovante oficial de inscrição</p><div class="receipt-number">#${esc(r.number)}-${esc(r.verifier)}</div></div><div class="receipt-details"><div class="receipt-detail"><span>Nome completo</span><strong>${esc(p.fullName||data.fullName||'—')}</strong></div><div class="receipt-detail"><span>Telefone</span><strong>${esc(p.phone||data.phone||'—')}</strong></div><div class="receipt-detail"><span>CPF</span><strong>${esc(maskedCPF(p.cpf||data.cpf||''))}</strong></div><div class="receipt-detail"><span>Data da inscrição</span><strong>${new Date(r.createdAt||Date.now()).toLocaleString('pt-BR')}</strong></div><div class="receipt-detail"><span>Evento</span><strong>${esc(r.eventName||settings.name)}</strong></div><div class="receipt-detail"><span>Status</span><strong>${r.paymentStatus==='paid'?'Pagamento validado':'Inscrição confirmada'}</strong></div>${Object.entries(data).filter(([k,v])=>v&& !['fullName','phone','cpf'].includes(k)).map(([k,v])=>`<div class="receipt-detail"><span>${esc((settings.fields||[]).find(f=>f.key===k)?.label||k)}</span><strong>${esc(typeof v==='string'?v:'Arquivo enviado')}</strong></div>`).join('')}</div><div class="receipt-code"><div id="qrCanvas"></div><svg id="barcode"></svg><small>Identificador: ${esc(r.token||randomToken())}</small></div><div class="receipt-sponsors">${(settings.sponsors||[]).map(s=>`<img src="${esc(s.url||s)}" alt="Patrocinador">`).join('')}</div><div class="receipt-footer">Desenvolvido por ${esc(settings.developerName||'SAN7 Tecnologia')} · Documento eletrônico para validação de inscrição.</div></article><div class="receipt-actions"><button class="btn btn-primary" id="downloadReceiptPdf">Baixar comprovante em PDF</button><button class="btn btn-outline" id="backToAccount">Minha conta</button></div>`;if(window.QRCode)new QRCode(root.querySelector('#qrCanvas'),{text:qrValue,width:116,height:116,colorDark:'#111111',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});if(window.JsBarcode)try{JsBarcode(root.querySelector('#barcode'),`${r.number}${r.verifier}`,{format:'CODE128',width:1.4,height:38,displayValue:true,fontSize:10,margin:0})}catch(e){}root.querySelector('#downloadReceiptPdf').onclick=()=>downloadReceiptPDF();root.querySelector('#backToAccount').onclick=()=>showView('account')}
async function downloadReceiptPDF(){const el=document.getElementById('receiptDocument');if(!el)return;const btn=document.getElementById('downloadReceiptPdf');btn.disabled=true;try{const canvas=await html2canvas(el,{scale:2,backgroundColor:'#ffffff',useCORS:true});const img=canvas.toDataURL('image/png');const {jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});const pageW=210,pageH=297,margin=12;let w=pageW-margin*2,h=canvas.height*w/canvas.width;if(h>pageH-margin*2){h=pageH-margin*2;w=canvas.width*h/canvas.height}pdf.addImage(img,'PNG',(pageW-w)/2,margin,w,h);pdf.save(`comprovante-${activeRegistration?.number||'inscricao'}.pdf`)}catch(e){toast('Não foi possível gerar o PDF. Tente novamente.')}finally{btn.disabled=false}}
function renderLookupResult(rows){const root=document.getElementById('lookupResults');if(!rows.length){root.innerHTML='<p class="empty-state">Nenhuma inscrição encontrada com esses dados.</p>';return}root.innerHTML=rows.map(r=>`<article class="registration-card" data-reg="${esc(r.id)}"><div><h3>${esc(r.eventName||settings.name)}</h3><p>Inscrição ${esc(r.number)}-${esc(r.verifier)}</p></div><span class="status ${r.paymentStatus==='paid'?'paid':'pending'}">${r.paymentStatus==='paid'?'Validada':'Aguardando'}</span></article>`).join('');root.querySelectorAll('[data-reg]').forEach(el=>el.onclick=()=>{const r=rows.find(x=>x.id===el.dataset.reg);if(r.paymentRequired&&r.paymentStatus!=='paid')showModal('Inscrição aguardando confirmação','O comprovante será liberado após a confirmação do pagamento.');else{activeRegistration=r;renderReceipt(r);showView('receipt')}})}
function initPublic(){initFirebase();loadSettings().then(()=>{renderWelcome();renderSections();renderSponsors()});document.getElementById('menuToggle')?.addEventListener('click',()=>document.getElementById('siteMenu').classList.toggle('open'));document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){e.preventDefault();const target=v.dataset.view;if(target==='register'&&!currentUser){showView('account');renderAccount('login','register')}else showView(target==='home'?'home':target);}});document.getElementById('showTerms')?.addEventListener('click',showTerms);document.getElementById('registrationForm')?.addEventListener('submit',submitRegistration);document.getElementById('lookupForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),name=String(fd.get('name')).trim().toLowerCase(),phone=digits(fd.get('phone'));try{const all=await dbGet('uniaoFitness/registrations')||{};const rows=Object.entries(all).filter(([id,r])=>String(r.profile?.fullName||r.data?.fullName||'').trim().toLowerCase()===name&&digits(r.profile?.phone||r.data?.phone||'')===phone).map(([id,r])=>({...r,id}));renderLookupResult(rows)}catch(err){toast('Não foi possível consultar agora.')}});document.getElementById('languageButton')?.addEventListener('click',()=>toast('Outros idiomas estarão disponíveis em breve.'));}


function initFirebase(){try{if(!firebase.apps.length)firebase.initializeApp(firebaseConfig);db=firebase.database();firebaseReady=true;auth=null;currentUser=null;userProfile=null;}catch(e){console.error(e);toast('Não foi possível conectar ao banco de dados.')}}
function syncAccountButton(){document.querySelectorAll('[data-view="account"]').forEach(x=>x.remove())}
function applyBranding(){document.documentElement.style.setProperty('--accent',settings.accent||'#f5c400');document.documentElement.style.setProperty('--font',settings.font||'Arial, sans-serif');const h=document.getElementById('siteHeader');if(h){h.style.background=settings.headerColor||'#111111';h.style.backgroundImage='none';h.style.color=contrastColor(settings.headerColor||'#111111');h.querySelectorAll('a,button').forEach(x=>x.style.color=contrastColor(settings.headerColor||'#111111'));h.querySelectorAll('.menu-toggle i').forEach(x=>x.style.background=contrastColor(settings.headerColor||'#111111'))}const name=document.getElementById('brandName');if(name)name.textContent=settings.name||DEFAULT_SETTINGS.name;const logo=document.getElementById('headerLogo');if(logo){logo.src=settings.headerLogo||'';logo.style.display=settings.headerLogo?'block':'none';logo.style.width=(settings.logoSize||42)+'px';logo.style.height=(settings.logoSize||42)+'px'}const title=document.getElementById('eventTitle');if(title)title.textContent=settings.eventTitle||'Inscrições abertas';const desc=document.getElementById('eventDescription');if(desc)desc.textContent=settings.eventDescription||'';document.title=settings.name||'União Fitness'}
function contrastColor(hex){let h=String(hex||'#111').replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');let n=parseInt(h,16);return ((n>>16)*.299+((n>>8)&255)*.587+(n&255)*.114)>150?'#111111':'#ffffff'}
function showView(view){document.querySelectorAll('#mainContent>section').forEach(s=>s.classList.add('hidden'));const target=document.getElementById(view+'View');if(target)target.classList.remove('hidden');document.getElementById('siteMenu')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});clearNotice();if(view==='register')prepareRegistration();if(view==='lookup'){const r=document.getElementById('lookupResults');if(r)r.innerHTML=''}}
function prepareRegistration(){const root=document.getElementById('registrationFields');if(!root)return;const fields=(settings.fields||DEFAULT_SETTINGS.fields).filter(f=>f.key!=='cpf'&&f.key!=='photo');root.innerHTML=buildField({key:'cpf',label:'CPF',type:'text',required:true})+fields.map(f=>buildField(f)).join('')+buildField({key:'photo',label:'Foto OBRIGATÓRIO',type:'file',required:false});const cpf=root.querySelector('[name="cpf"]');cpf.inputMode='numeric';cpf.maxLength=14;cpf.addEventListener('input',()=>cpf.value=maskCPF(cpf.value));bindFloating(root);let askedFor='';cpf.addEventListener('blur',async()=>{const raw=digits(cpf.value);if(raw.length!==11||!validCPF(raw)||askedFor===raw)return;askedFor=raw;try{const all=await dbGet('uniaoFitness/registrations')||{};const match=Object.values(all).filter(r=>digits(r.data?.cpf||r.profile?.cpf)===raw).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0))[0];if(!match)return;const vals={...(match.data||{}),...(match.profile||{})};const preview=fields.map(f=>vals[f.key]?`<div class="cpf-preview-row"><span>${esc(f.label)}</span><strong>${esc(String(vals[f.key]))}</strong></div>`:'').join('');showModal('Você já usou este CPF para inscrições?','<p>Encontramos dados associados a este CPF. Deseja aproveitar os dados abaixo?</p><div class="cpf-preview-row"><span>CPF</span><strong>'+esc(maskCPF(raw))+'</strong></div>'+preview,'<button class="btn btn-outline" id="dontUseSaved">Não, preencher manualmente</button><button class="btn btn-primary" id="useSaved">Sim, aproveitar dados</button>');document.getElementById('dontUseSaved').onclick=()=>document.getElementById('modalRoot').innerHTML='';document.getElementById('useSaved').onclick=()=>{fields.forEach(f=>{const el=root.querySelector(`[name="${CSS.escape(f.key)}"]`);if(el&&vals[f.key]&&el.type!=='file')el.value=String(vals[f.key]);});cpf.value=maskCPF(raw);bindFloating(root);document.getElementById('modalRoot').innerHTML='';toast('Dados preenchidos. Confira antes de continuar.')}}catch(e){console.error(e)}})}
async function submitRegistration(e){e.preventDefault();const form=e.currentTarget,btn=form.querySelector('[type="submit"]'),err=document.getElementById('formError');err.textContent='';const cpf=digits(form.querySelector('[name="cpf"]')?.value);if(!validCPF(cpf)){err.textContent='Informe um CPF válido.';form.querySelector('[name="cpf"]')?.focus();return}const invalid=[...form.querySelectorAll('[required]')].find(el=>!el.checkValidity());if(invalid){invalid.closest('.floating-field')?.classList.add('invalid');invalid.focus();err.textContent='Preencha os campos obrigatórios destacados.';return}if(!document.getElementById('termsAccepted').checked){err.textContent='Você precisa aceitar os termos de uso.';return}btn.disabled=true;try{const all=await dbGet('uniaoFitness/registrations')||{};if(Object.values(all).some(r=>digits(r.data?.cpf||r.profile?.cpf)===cpf&&(r.eventId||'default')===(settings.eventId||'default')))throw Error('Este CPF já possui inscrição neste evento. Consulte sua inscrição pelo CPF.');const fd=new FormData(form),data={};for(const f of settings.fields||DEFAULT_SETTINGS.fields){if(f.key==='cpf')continue;const val=fd.get(f.key);if(f.type==='file'){if(val&&val.size)data[f.key]=await uploadCloudinary(val)}else data[f.key]=String(val||'').trim()}data.cpf=cpf;const photo=fd.get('photo');if(photo&&photo.size)data.photo=await uploadCloudinary(photo);const nums=Object.values(all).map(r=>parseInt(r.number,10)).filter(Number.isFinite);const number=String((nums.length?Math.max(...nums):0)+1).padStart(4,'0');const p=settings.payment||{};const record={eventId:settings.eventId||'default',eventName:settings.eventTitle||settings.name||'Evento',number,verifier:verifier(number),token:randomToken(),data,profile:{fullName:data.fullName||'',cpf,phone:data.phone||'',photo:data.photo||''},createdAt:Date.now(),paymentStatus:p.enabled?'pending':'paid',paymentRequired:!!p.enabled,amount:p.amount||'',verifiedAt:p.enabled?null:Date.now()};const id=await dbPush('uniaoFitness/registrations',record);activeRegistration={...record,id};if(p.enabled)renderPayment(activeRegistration);else{await renderReceipt(activeRegistration);showView('receipt')}toast('Inscrição registrada com sucesso.')}catch(ex){err.textContent=ex.message||'Não foi possível concluir a inscrição.'}finally{btn.disabled=false}}
function renderPayment(r){showView('payment');const root=document.getElementById('paymentView'),p=settings.payment||{};const amount=p.amount||'Consulte a administração';const wa=digits(p.whatsapp||'');root.innerHTML=`<div class="view-heading"><p class="eyebrow">INSCRIÇÃO REGISTRADA</p><h1>Finalize seu pagamento</h1><p>Leia as instruções antes de continuar.</p></div><div class="form-panel payment-emphasis"><p class="payment-alert">ESTE É UM EVENTO PAGO</p><div class="payment-amount">${esc(amount)}</div><p>1. Entre no aplicativo do seu banco e realize o pagamento usando a chave Pix abaixo.</p><div class="copy-row"><code>${esc(p.pixKey||'Chave Pix não cadastrada')}</code><button class="btn-small" id="copyPix">Copiar chave</button></div><p>2. Após pagar, clique no botão abaixo e envie o comprovante pelo WhatsApp para a equipe administrativa.</p><a class="btn btn-primary payment-whatsapp" target="_blank" rel="noopener" href="${wa?'https://wa.me/'+wa+'?text='+encodeURIComponent('Olá! Enviei o pagamento do evento '+r.eventName+', inscrição '+r.number+'. CPF: '+r.data.cpf+'.'):'#'}">Enviar comprovante pelo WhatsApp</a><p class="payment-warning">IMPORTANTE: depois que a equipe administrativa confirmar o pagamento, você poderá consultar sua inscrição e abrir o comprovante. A validação ocorre em até cinco horas após o envio do comprovante.</p><button class="btn btn-outline" id="goLookup">Consultar inscrição</button><p class="admin-note">Número da inscrição: ${esc(r.number)}-${esc(r.verifier)}</p></div>`;root.querySelector('#copyPix').onclick=()=>navigator.clipboard?.writeText(p.pixKey||'').then(()=>toast('Chave Pix copiada.')).catch(()=>toast('Copie a chave manualmente.'));root.querySelector('#goLookup').onclick=()=>showView('lookup')}
async function renderReceipt(r){const root=document.getElementById('receiptView');if(!root)return;const data=r.data||{},pending=r.paymentRequired&&r.paymentStatus!=='paid';root.innerHTML=`<div class="view-heading"><p class="eyebrow">DOCUMENTO DIGITAL</p><h1>Comprovante de inscrição</h1><p>Inscrição ${esc(r.number)}-${esc(r.verifier)}</p></div>${pending?`<div class="payment-warning">PAGAMENTO AGUARDANDO CONFIRMAÇÃO. Se você já enviou o comprovante pelo WhatsApp, a equipe administrativa fará a validação em até cinco horas. Depois da confirmação, consulte novamente para acessar o comprovante oficial.</div>`:''}<article id="receiptDocument" class="document-card"><div class="receipt-top"><h2>${esc(settings.name||'União Fitness')}</h2><p>Documento de inscrição</p><div class="receipt-number">#${esc(r.number)}-${esc(r.verifier)}</div></div><div class="receipt-details">${[['Nome completo',data.fullName],['CPF',maskCPF(data.cpf||'')],['Evento',r.eventName],['Data da inscrição',new Date(r.createdAt||Date.now()).toLocaleString('pt-BR')],['Pagamento',pending?'Aguardando confirmação':'Confirmado']].map(([a,b])=>`<div class="receipt-detail"><span>${esc(a)}</span><strong>${esc(b||'—')}</strong></div>`).join('')}</div><div class="receipt-pdf-mark"><span>PDF</span><strong>Comprovante_${esc(r.number)}.pdf</strong><small>Clique em “Abrir documento” ou tire um print desta tela se não conseguir baixar.</small></div></article><div class="receipt-actions"><button class="btn btn-primary" id="downloadReceiptPdf">Baixar em PDF</button><button class="btn btn-outline" id="backToLookup">Voltar à consulta</button></div>`;root.querySelector('#downloadReceiptPdf').onclick=()=>downloadReceiptPDF();root.querySelector('#backToLookup').onclick=()=>showView('lookup')}
function renderLookupResult(rows){const root=document.getElementById('lookupResults');if(!rows.length){root.innerHTML='<p class="empty-state">Nenhuma inscrição encontrada para este CPF.</p>';return}root.innerHTML='<h2>Inscrições encontradas</h2>'+rows.map(r=>`<article class="registration-card" data-reg="${esc(r.id)}"><div><h3>${esc(r.eventName||settings.name)}</h3><p>Inscrição ${esc(r.number)} · ${new Date(r.createdAt||Date.now()).toLocaleDateString('pt-BR')}</p><p>Toque para abrir o documento e ver o status.</p></div><span class="status ${r.paymentStatus==='paid'?'paid':'pending'}">${r.paymentStatus==='paid'?'Pagamento confirmado':r.paymentRequired?'Aguardando pagamento':'Inscrição confirmada'}</span></article>`).join('');root.querySelectorAll('[data-reg]').forEach(el=>el.onclick=async()=>{const r=rows.find(x=>x.id===el.dataset.reg);activeRegistration=r;await renderReceipt(r);showView('receipt')})}
function initPublic(){initFirebase();loadSettings().then(()=>{renderWelcome();renderSections();renderSponsors()});document.getElementById('menuToggle')?.addEventListener('click',()=>document.getElementById('siteMenu')?.classList.toggle('open'));document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){e.preventDefault();showView(v.dataset.view==='home'?'home':v.dataset.view)}});document.getElementById('showTerms')?.addEventListener('click',showTerms);document.getElementById('registrationForm')?.addEventListener('submit',submitRegistration);const lf=document.getElementById('lookupForm');lf?.addEventListener('submit',async e=>{e.preventDefault();const cpf=digits(new FormData(lf).get('cpf'));if(!validCPF(cpf)){toast('Informe um CPF válido.');return}try{const all=await dbGet('uniaoFitness/registrations')||{};const rows=Object.entries(all).filter(([id,r])=>digits(r.data?.cpf||r.profile?.cpf)===cpf).map(([id,r])=>({...r,id})).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));renderLookupResult(rows)}catch(ex){toast('Não foi possível consultar agora. Verifique a conexão.')}});const ci=lf?.querySelector('[name="cpf"]');ci?.addEventListener('input',()=>ci.value=maskCPF(ci.value));document.getElementById('languageButton')?.remove();document.querySelectorAll('[data-view="account"]').forEach(x=>x.remove());}


/* Atualizações da reformulação: voz das instruções, comprovante em modal e PDF real. */
const PAYMENT_VOICE_TEXT='Realize o pagamento e envie o comprovante pelo WhatsApp no botão abaixo. Após enviar o comprovante de pagamento, seu comprovante de inscrição estará disponível em até cinco horas. Você voltará ao site e poderá consultar sua inscrição pelo CPF e baixar ou tirar print desse comprovante.';
let ufSpeechVoices=[];
function getPreferredSpeechVoice(){
  if(!('speechSynthesis' in window)) return null;
  const voices=window.speechSynthesis.getVoices();
  const pref=settings.receiptVoiceGender||'female';
  const pt=voices.filter(v=>/^pt(-|_)/i.test(v.lang||''));
  const google=pt.filter(v=>/google/i.test(v.name||''));
  const pool=google.length?google:(pt.length?pt:voices);
  const hints=pref==='male'?/(male|mascul|daniel|ricardo|antonio|felipe|google português do brasil)/i:/(female|fem|woman|mulher|francisca|maria|luciana|google português do brasil)/i;
  return pool.find(v=>hints.test(v.name||''))||pool[0]||null;
}
function speakPaymentInstructions(){
  if(!('speechSynthesis' in window)) return;
  window.speechSynthesis.cancel();
  const utterance=new SpeechSynthesisUtterance('Escute com atenção. '+PAYMENT_VOICE_TEXT);
  utterance.lang='pt-BR'; utterance.rate=0.96; utterance.pitch=1;
  const voice=getPreferredSpeechVoice(); if(voice) utterance.voice=voice;
  window.speechSynthesis.speak(utterance);
}
function renderPayment(r){
  showView('payment'); const root=document.getElementById('paymentView'),p=settings.payment||{};
  const wa=digits(p.whatsapp||'');
  root.innerHTML=`<div class="view-heading"><p class="eyebrow">INSCRIÇÃO REGISTRADA</p><h1>Finalize seu pagamento</h1><p>Realize o pagamento e envie o comprovante pelo WhatsApp.</p></div><div class="form-panel payment-emphasis"><p class="payment-alert">ESTE É UM EVENTO PAGO</p><div class="payment-amount">${esc(p.amount||'Consulte a administração')}</div><p>1. Entre no aplicativo do seu banco e realize o pagamento usando a chave Pix abaixo.</p><div class="copy-row"><code>${esc(p.pixKey||'Chave Pix não cadastrada')}</code><button class="btn-small" id="copyPix">Copiar chave</button></div><p>2. Após pagar, envie o comprovante pelo botão abaixo.</p><a class="btn btn-primary payment-whatsapp" id="sendPaymentWhatsapp" target="_blank" rel="noopener" href="${wa?'https://wa.me/'+wa+'?text='+encodeURIComponent('Olá! Estou enviando o comprovante de pagamento. Nome completo: '+(r.profile?.fullName||r.data?.fullName||r.data?.nomeCompleto||r.data?.nome||'Não informado')+'. Evento: '+r.eventName+'. Inscrição: '+r.number+'-'+r.verifier+'. CPF: '+(r.data?.cpf||r.profile?.cpf||'')+'. Por favor, confirme o recebimento.'):'#'}">Enviar comprovante pelo WhatsApp</a><p class="payment-warning">Após enviar o comprovante, a equipe fará a validação em até cinco horas. Depois, volte ao site e consulte pelo CPF para abrir seu comprovante de inscrição.</p><button class="btn btn-outline" id="goLookup">Consultar inscrição</button><p class="admin-note">Número da inscrição: ${esc(r.number)}-${esc(r.verifier)}</p></div>`;
  root.querySelector('#copyPix').onclick=()=>navigator.clipboard?.writeText(p.pixKey||'').then(()=>toast('Chave Pix copiada.')).catch(()=>toast('Copie a chave manualmente.'));
  root.querySelector('#goLookup').onclick=()=>showView('lookup');
  // A fala é iniciada automaticamente ao entrar na etapa de pagamento. Alguns navegadores
  // exigem interação prévia; nesse caso, o botão de repetição continua disponível.
  setTimeout(speakPaymentInstructions,250);
  root.insertAdjacentHTML('beforeend','<button type="button" class="btn btn-outline voice-repeat" id="repeatPaymentVoice">Ouvir instruções novamente</button>');
  root.querySelector('#repeatPaymentVoice').onclick=speakPaymentInstructions;
}
function openReceiptOverlay(){
  const source=document.getElementById('receiptDocument'); if(!source)return;
  const root=document.getElementById('modalRoot');
  root.innerHTML=`<div class="modal-backdrop receipt-overlay" role="presentation"><div class="modal receipt-modal" role="dialog" aria-modal="true" aria-label="Comprovante de inscrição"><button class="modal-close" aria-label="Fechar">×</button><div class="receipt-overlay-content">${source.outerHTML}</div><div class="admin-actions"><button class="btn btn-primary" id="overlayDownload">Baixar PDF</button></div></div></div>`;
  root.querySelector('.modal-close').onclick=()=>root.innerHTML='';
  root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};
  const qr=root.querySelector('#qrCanvas'); if(qr&&window.QRCode&&activeRegistration){qr.innerHTML='';new QRCode(qr,{text:`UF|${activeRegistration.id}|${activeRegistration.number}-${activeRegistration.verifier}|${activeRegistration.token||''}`,width:116,height:116,correctLevel:QRCode.CorrectLevel.M})}
  const barcode=root.querySelector('#barcode');if(barcode&&window.JsBarcode&&activeRegistration){try{JsBarcode(barcode,`${activeRegistration.number}${activeRegistration.verifier}`,{format:'CODE128',width:1.4,height:38,displayValue:true,fontSize:10,margin:0})}catch(e){}}
  root.querySelector('#overlayDownload').onclick=downloadReceiptPDF;
}
async function renderReceipt(r){
 const root=document.getElementById('receiptView');if(!root)return;
 const pending=!!r.paymentRequired&&r.paymentStatus!=='paid';
 if(pending){root.innerHTML=`<div class="view-heading"><p class="eyebrow">INSCRIÇÃO REGISTRADA</p><h1>Comprovante indisponível</h1><p>Inscrição ${esc(r.number)}-${esc(r.verifier)}</p></div><button type="button" class="receipt-preview-trigger" id="pendingReceiptNotice"><span class="receipt-file-icon">PDF</span><span><strong>Comprovante_${esc(r.number||'inscricao')}.pdf</strong><small>Documento aguardando liberação</small></span><span class="receipt-open-label">Ver status</span></button><div class="payment-warning">PAGAMENTO AGUARDANDO CONFIRMAÇÃO. Se você já enviou o comprovante pelo WhatsApp, aguarde até cinco horas para a validação. O comprovante oficial só fica disponível após a confirmação do pagamento. Volte e consulte sua inscrição pelo CPF.</div><div class="receipt-actions"><button class="btn btn-outline" id="backToLookup">Voltar à consulta</button></div>`;root.querySelector('#pendingReceiptNotice').onclick=()=>showModal('Comprovante ainda não disponível','<p>Se você já enviou o comprovante de pagamento pelo WhatsApp, aguarde até cinco horas. Após a confirmação administrativa, consulte novamente pelo CPF para acessar e baixar o comprovante oficial.</p>','<button class="btn btn-primary" id="closePendingReceipt">Entendi</button>');document.getElementById('closePendingReceipt')?.addEventListener('click',()=>document.getElementById('modalRoot').innerHTML='');root.querySelector('#backToLookup').onclick=()=>showView('lookup');return;}
 const data=r.data||{},p=r.profile||{};const fields=Object.entries(data).filter(([k,v])=>v&&!['fullName','nomeCompleto','nome','nome_completo','phone','telefone','cpf','photo','foto','image'].includes(k));
 const fullName=p.fullName||p.nomeCompleto||p.nome||data.fullName||data.nomeCompleto||data.nome||data.nome_completo||data['Nome completo']||(settings.fields||[]).find(f=>/nome\s*completo/i.test(f.label||'')&&data[f.key])&&data[(settings.fields||[]).find(f=>/nome\s*completo/i.test(f.label||'')).key]||'—';
 const phone=p.phone||data.phone||data.telefone||data.celular||'—',cpf=p.cpf||data.cpf||data.CPF||'';
 const qrValue=`UF|${r.id}|${r.number}-${r.verifier}|${r.token||''}`;
 root.innerHTML=`<div class="view-heading"><p class="eyebrow">DOCUMENTO DIGITAL</p><h1>Comprovante de inscrição</h1><p>Toque no documento para ampliar e abrir sobre a tela.</p></div><button type="button" class="receipt-preview-trigger" id="openReceiptDocument" aria-label="Abrir comprovante"><span class="receipt-file-icon">PDF</span><span><strong>Comprovante_${esc(r.number||'inscricao')}.pdf</strong><small>Documento digital · Toque para visualizar</small></span><span class="receipt-open-label">Abrir documento</span></button><article id="receiptDocument" class="document-card" style="--watermark:url('${esc(settings.watermark||settings.headerLogo||'')}')"><div class="receipt-top">${settings.headerLogo?`<img class="receipt-logo" style="width:${Number(settings.receiptLogoSize||100)}px" src="${esc(settings.headerLogo)}" alt="Logo">`:''}<h2>${esc(settings.name||'União Fitness')}</h2><p>Comprovante oficial de inscrição</p><div class="receipt-number">#${esc(r.number)}-${esc(r.verifier)}</div></div><div class="receipt-details"><div class="receipt-detail"><span>Nome completo</span><strong>${esc(fullName)}</strong></div><div class="receipt-detail"><span>Telefone</span><strong>${esc(phone)}</strong></div><div class="receipt-detail"><span>CPF</span><strong>${esc(maskCPF(String(cpf)))}</strong></div><div class="receipt-detail"><span>Data e hora da inscrição</span><strong>${new Date(r.createdAt||Date.now()).toLocaleString('pt-BR')}</strong></div><div class="receipt-detail"><span>Evento</span><strong>${esc(r.eventName||settings.name||'—')}</strong></div><div class="receipt-detail"><span>Status</span><strong>${r.paymentRequired?'Pagamento validado':'Inscrição confirmada'}</strong></div>${fields.map(([k,v])=>`<div class="receipt-detail"><span>${esc((settings.fields||[]).find(f=>f.key===k)?.label||k)}</span><strong>${esc(typeof v==='string'?v:'Arquivo enviado')}</strong></div>`).join('')}</div><div class="receipt-code"><div id="qrCanvas"></div><svg id="barcode"></svg><small>Identificador: ${esc(r.token||'')}</small></div><div class="receipt-sponsors">${(settings.sponsors||[]).map(x=>`<img src="${esc(x.url||x)}" alt="Patrocinador">`).join('')}</div><div class="receipt-footer">Desenvolvido por ${esc(settings.developerName||'SAN7 Tecnologia')} · Documento eletrônico para validação de inscrição.</div></article><div class="receipt-actions"><button class="btn btn-primary" id="downloadReceiptPdf">Baixar comprovante em PDF</button><button class="btn btn-outline" id="backToLookup">Voltar à consulta</button></div>`;
 if(window.QRCode)new QRCode(root.querySelector('#qrCanvas'),{text:qrValue,width:116,height:116,colorDark:'#111111',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});
 if(window.JsBarcode)try{JsBarcode(root.querySelector('#barcode'),`${r.number}${r.verifier}`,{format:'CODE128',width:1.4,height:38,displayValue:true,fontSize:10,margin:0})}catch(e){}
 root.querySelector('#openReceiptDocument').onclick=openReceiptOverlay;root.querySelector('#receiptDocument').onclick=openReceiptOverlay;root.querySelector('#downloadReceiptPdf').onclick=downloadReceiptPDF;root.querySelector('#backToLookup').onclick=()=>showView('lookup');
}
async function downloadReceiptPDF(){
  const el=document.querySelector('#modalRoot #receiptDocument')||document.getElementById('receiptDocument');if(!el)return;
  const btn=document.getElementById('downloadReceiptPdf')||document.getElementById('overlayDownload');if(btn)btn.disabled=true;
  try{const canvas=await html2canvas(el,{scale:2,backgroundColor:'#ffffff',useCORS:true,logging:false});const img=canvas.toDataURL('image/png');const {jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});const pw=210,ph=297,margin=12;let w=pw-margin*2,h=canvas.height*w/canvas.width;if(h>ph-margin*2){h=ph-margin*2;w=canvas.width*h/canvas.height}pdf.addImage(img,'PNG',(pw-w)/2,margin,w,h);pdf.save(`comprovante-${activeRegistration?.number||'inscricao'}.pdf`)}catch(e){console.error(e);toast('Não foi possível gerar o PDF. Verifique se as imagens estão acessíveis e tente novamente.')}finally{if(btn)btn.disabled=false}
}
function renderLookupResult(rows){
 const root=document.getElementById('lookupResults');
 if(!rows.length){root.innerHTML='<p class="empty-state">Nenhuma inscrição encontrada para este CPF.</p>';return}
 root.innerHTML='<h2>Inscrições encontradas</h2>'+rows.map(r=>`<button type="button" class="registration-card lookup-document-card" data-reg="${esc(r.id)}"><span class="receipt-file-icon">PDF</span><span class="lookup-doc-copy"><strong>${esc(r.eventName||settings.name)}</strong><small>Inscrição ${esc(r.number)}-${esc(r.verifier)} · ${new Date(r.createdAt||Date.now()).toLocaleDateString('pt-BR')}</small><small>Toque para abrir o comprovante</small></span><span class="status ${r.paymentStatus==='paid'?'paid':'pending'}">${r.paymentStatus==='paid'?'Validada':r.paymentRequired?'Aguardando':'Confirmada'}</span></button>`).join('');
 root.querySelectorAll('[data-reg]').forEach(el=>el.onclick=async()=>{const r=rows.find(x=>x.id===el.dataset.reg);activeRegistration=r;await renderReceipt(r);showView('receipt');});
}
